solutionCode:
public class Solution {
    static class SegMin {
        private final int n;
        private final int[] t;

        SegMin(int[] a) {
            n = a.length;
            t = new int[2 * n];
            System.arraycopy(a, 0, t, n, n);
            for (int i = n - 1; i > 0; i--) t[i] = Math.min(t[2 * i], t[2 * i + 1]);
        }

        void set(int i, int valor) {
            for (t[i += n] = valor; i > 1; i >>= 1) t[i >> 1] = Math.min(t[i], t[i ^ 1]);
        }

        // Sobe pelas duas bordas: um índice ímpar à esquerda (par à direita) é um nó inteiro dentro do intervalo.
        int min(int l, int r) {
            int res = Integer.MAX_VALUE;
            for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
                if ((l & 1) == 1) res = Math.min(res, t[l++]);
                if ((r & 1) == 1) res = Math.min(res, t[--r]);
            }
            return res;
        }
    }
}

