import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    @Test void pequeno() {
        var s = new Solution.SegMin(new int[]{5, 2, 8, 6, 3, 7});
        assertEquals(2, s.min(0, 6));
        assertEquals(3, s.min(2, 5));
        assertEquals(8, s.min(2, 3));
        assertEquals(Integer.MAX_VALUE, s.min(3, 3));
        s.set(1, 10);
        assertEquals(3, s.min(0, 6));
        s.set(5, -1);
        assertEquals(-1, s.min(4, 6));
    }

    @Test void tamanhoNaoPotenciaDeDois() {
        var rnd = new Random(17);
        for (int n = 1; n <= 20; n++) {
            int[] a = rnd.ints(n, -50, 50).toArray();
            var s = new Solution.SegMin(a);
            for (int op = 0; op < 200; op++) {
                if (rnd.nextBoolean()) {
                    int i = rnd.nextInt(n), v = rnd.nextInt(100) - 50;
                    a[i] = v;
                    s.set(i, v);
                } else {
                    int l = rnd.nextInt(n + 1), r = l + rnd.nextInt(n - l + 1);
                    int esperado = Integer.MAX_VALUE;
                    for (int i = l; i < r; i++) esperado = Math.min(esperado, a[i]);
                    assertEquals(esperado, s.min(l, r), "n=" + n + " [" + l + "," + r + ")");
                }
            }
        }
    }

    @Test void grande() {
        int n = 200_000;
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = n - i;
        var s = new Solution.SegMin(a);
        long soma = 0;
        for (int i = 0; i < 200_000; i++) {
            s.set(i % n, i);
            soma += s.min(0, n);
        }
        assertTrue(soma >= 0);
        assertEquals(0, s.min(0, 1));
    }
}
